import React, { useState } from 'react';
import { FlatList, Linking, ScrollView, StyleSheet, Text, useWindowDimensions, View } from 'react-native';
import { ListRow, Sheet } from '@/components/ui';
import { useTheme } from '@/hooks/useTheme';
import { metrics, type } from '@/theme/theme';
import licences from '@/data/licences.json';

/**
 * Open-source notices for everything the app ships. The list is generated by
 * scripts/gen-licences.js; FFmpeg's entry is what LGPL asks of us: the notice, the full
 * licence text and where its source is.
 */
type Entry = (typeof licences.entries)[number] & { notice?: string; source?: string };

const texts = licences.texts as Record<string, string>;

export function LicencesSheet({ visible, onClose }: { visible: boolean; onClose: () => void }) {
    const { colors } = useTheme();
    const { height } = useWindowDimensions();
    const [open, setOpen] = useState<Entry | null>(null);

    const close = () => {
        setOpen(null);
        onClose();
    };

    return (
        <Sheet
            visible={visible}
            onClose={close}
            title={open ? open.name : 'Open source licences'}
            onBack={open ? () => setOpen(null) : undefined}
        >
            {open ? (
                <ScrollView style={{ height: height * 0.6 }} contentContainerStyle={styles.text}>
                    {open.notice ? (
                        <Text style={[type.body, { color: colors.text }]}>{open.notice}</Text>
                    ) : null}
                    {open.source ? (
                        <View style={[styles.row, { backgroundColor: colors.fill }]}>
                            <ListRow
                                icon="external-link"
                                title="Source code"
                                caption={open.source}
                                onPress={() => Linking.openURL(open.source!).catch(() => {})}
                            />
                        </View>
                    ) : null}
                    <Text selectable style={[type.caption, { color: colors.textSecondary }]}>
                        {texts[open.text]}
                    </Text>
                </ScrollView>
            ) : (
                <FlatList
                    style={{ height: height * 0.6 }}
                    data={licences.entries as Entry[]}
                    keyExtractor={(item) => item.name}
                    ItemSeparatorComponent={Gap}
                    renderItem={({ item }) => (
                        <View style={[styles.row, { backgroundColor: colors.fill }]}>
                            <ListRow title={item.name} caption={item.license} chevron onPress={() => setOpen(item)} />
                        </View>
                    )}
                />
            )}
        </Sheet>
    );
}

const Gap = () => <View style={styles.gap} />;

const styles = StyleSheet.create({
    text: { gap: metrics.space.md, paddingBottom: metrics.space.lg },
    row: { borderRadius: 4, overflow: 'hidden' },
    gap: { height: 2 },
});
